foreignObject.xhtml:script:

// === GLOBALS ===
let allGames = [];

// === LAAD ALLE GAMES ===
function loadGames() {
  const loading = document.getElementById('loadingIndicator');
  const error = document.getElementById('errorIndicator');
  const grid = document.getElementById('gameGrid');

  if (!window.nex || !window.nex.metadata) {
    setTimeout(loadGames, 500);
    return;
  }

  try {
    const games = window.nex.metadata.getAllMetadata();
    allGames = Object.values(games);

    if (allGames.length === 0) throw new Error('No games found');

    loading.style.display = 'none';
    error.style.display = 'none';
    grid.style.display = 'block';

    grid.innerHTML = '';

    const cols = 6;
    const spacing = 20;
    const cardWidth = 260;
    const cardHeight = 220;

    let x = (1920 - (cols * (cardWidth + spacing) - spacing)) / 2;
    let y = 160;

    allGames.forEach((game, index) => {
      const col = index % cols;
      const row = Math.floor(index / cols);

      const cx = x + col * (cardWidth + spacing);
      const cy = y + row * (cardHeight + spacing);

      const card = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      card.setAttribute('class', 'game-card');
      card.setAttribute('onclick', `loadGame('${game.alias}')`);
      card.setAttribute('transform', `translate(${cx}, ${cy})`);

      const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      rect.setAttribute('width', cardWidth);
      rect.setAttribute('height', cardHeight);
      card.appendChild(rect);

      // Thumbnail
      const thumbRect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      thumbRect.setAttribute('x', 10);
      thumbRect.setAttribute('y', 10);
      thumbRect.setAttribute('width', cardWidth - 20);
      thumbRect.setAttribute('height', 120);
      thumbRect.setAttribute('rx', '6');
      thumbRect.setAttribute('fill', '#0a0a0f');
      card.appendChild(thumbRect);

      // Thumbnail image
      const fo = document.createElementNS('http://www.w3.org/2000/svg', 'foreignObject');
      fo.setAttribute('x', 10);
      fo.setAttribute('y', 10);
      fo.setAttribute('width', cardWidth - 20);
      fo.setAttribute('height', 120);

      const imgDiv = document.createElement('xhtml:div');
      imgDiv.setAttribute('xmlns', 'http://www.w3.org/1999/xhtml');
      imgDiv.style.cssText = 'width:100%; height:100%; overflow:hidden; border-radius:6px; background:#0a0a0f; display:flex; align-items:center; justify-content:center;';
      imgDiv.innerHTML = `<xhtml:img src="${game.img || ''}" alt="${game.name}" style="width:100%; height:100%; object-fit:cover;" onerror="this.style.display='none';this.parentElement.innerHTML='<span style=\\'font-size:32px;color:#444466;\\'>🎮</span>';">`;
      fo.appendChild(imgDiv);
      card.appendChild(fo);

      // Game naam
      const name = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      name.setAttribute('x', cardWidth / 2);
      name.setAttribute('y', 158);
      name.setAttribute('text-anchor', 'middle');
      name.setAttribute('class', 'game-name');
      name.textContent = game.name;
      card.appendChild(name);

      // Game categorie
      const category = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      category.setAttribute('x', cardWidth / 2);
      category.setAttribute('y', 182);
      category.setAttribute('text-anchor', 'middle');
      category.setAttribute('class', 'game-category');
      category.textContent = game.category || 'Game';
      card.appendChild(category);

      grid.appendChild(card);
    });

    console.log(`✅ ${allGames.length} games geladen!`);

  } catch (err) {
    console.error('Error:', err);
    loading.style.display = 'none';
    error.style.display = 'block';
  }
}

// === LAAD GAME IN IFRAME ===
function loadGame(alias) {
  const wrapper = document.getElementById('gameWrapper');
  const frame = document.getElementById('gameFrame');

  if (!wrapper || !frame) return;

  // Genereer HTML voor de game
  const gameHTML = `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="UTF-8">
      <meta name="viewport" content="width=device-width, initial-scale=1.0">
      <title>${alias}</title>
      <script src="https://cdn.jsdelivr.net/gh/UseNex/nex-js@f60df53fb5554e4e160c086b47bf71f6a213e42c/nex.min.js"><\/script>
      <style>
        * { margin:0; padding:0; box-sizing:border-box; }
        body { background:#0a0a0f; width:100vw; height:100vh; overflow:hidden; display:flex; align-items:center; justify-content:center; }
        nex-game { display:block; width:100vw; height:100vh; }
      </style>
    </head>
    <body>
      <nex-game id="game" alias="${alias}" gid="game-${Date.now()}"></nex-game>
      <script>
        const gid = document.getElementById('game').getAttribute('gid');
        const checkReady = setInterval(() => {
          if (window.nex && window.nex[gid]) {
            clearInterval(checkReady);
            window.nex[gid].on('ready', () => {
              if (window.nex[gid]) window.nex[gid].start();
            });
            window.nex[gid].on('error', (err) => {
              console.error('Game error:', err);
            });
          }
        }, 200);
      <\/script>
    </body>
    </html>
  `;

  // Schrijf naar iframe
  const doc = frame.contentDocument || frame.contentWindow.document;
  doc.open();
  doc.write(gameHTML);
  doc.close();

  // Toon wrapper
  wrapper.style.display = 'block';
}

// === SLUIT GAME ===
function closeGame() {
  const wrapper = document.getElementById('gameWrapper');
  const frame = document.getElementById('gameFrame');

  if (wrapper) wrapper.style.display = 'none';
  if (frame) frame.src = 'about:blank';
}

// === BACK BUTTON IN SVG ===
// We maken een back button in de SVG die closeGame aanroept
function createBackButton() {
  const container = document.getElementById('gameContainer');
  if (!container) return;

  // Voeg back button toe als SVG element
  const backBtn = document.createElementNS('http://www.w3.org/2000/svg', 'g');
  backBtn.setAttribute('class', 'back-btn');
  backBtn.setAttribute('onclick', 'closeGame()');
  backBtn.setAttribute('transform', 'translate(30, 30)');
  backBtn.setAttribute('id', 'backButton');
  backBtn.style.display = 'none';

  const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
  rect.setAttribute('width', '160');
  rect.setAttribute('height', '44');
  backBtn.appendChild(rect);

  const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
  text.setAttribute('x', '80');
  text.setAttribute('y', '28');
  text.setAttribute('text-anchor', 'middle');
  text.setAttribute('fill', '#ffffff');
  text.setAttribute('font-family', 'Inter, sans-serif');
  text.setAttribute('font-size', '14px');
  text.textContent = '← Back to games';
  backBtn.appendChild(text);

  // Voeg toe aan SVG
  const svg = document.getElementById('mainSvg');
  svg.appendChild(backBtn);

  // Monitor voor game container
  const observer = new MutationObserver(() => {
    const wrapper = document.getElementById('gameWrapper');
    const backBtn = document.getElementById('backButton');
    if (wrapper && backBtn) {
      backBtn.style.display = wrapper.style.display === 'block' ? 'block' : 'none';
    }
  });

  const wrapper = document.getElementById('gameWrapper');
  if (wrapper) {
    observer.observe(wrapper, { attributes: true, attributeFilter: ['style'] });
  }
}

// === INITIALISEER ===
function init() {
  if (window.nex && window.nex.metadata) {
    loadGames();
    createBackButton();
  } else {
    setTimeout(init, 500);
  }
}

// Wacht tot DOM klaar is
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}

// Fallback: blijf proberen
setTimeout(() => {
  if (!window.nex || !window.nex.metadata) {
    console.warn('⚠️ Nex niet geladen, probeer opnieuw...');
    loadGames();
  }
}, 3000);
